// cells/drive/client/coast-baked.ts
var COAST_W = 720;
var COAST_H = 360;
var COAST_STEP = 0.5;
var COAST_MAX_KM = 3e3;
var COAST_B64 = "";

// cells/drive/client/coast.ts
var grid = null;
function load() {
  if (grid) return grid;
  const bin = atob(COAST_B64);
  const g = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) g[i] = bin.charCodeAt(i);
  grid = g;
  return g;
}
function coastKm(lat, lon) {
  const g = load();
  const i = Math.min(COAST_W - 1, Math.max(0, Math.floor((lon + 180) % 360 / COAST_STEP)));
  const j = Math.min(COAST_H - 1, Math.max(0, Math.floor((90 - lat) / COAST_STEP)));
  const v = g[j * COAST_W + i] / 255;
  return v * v * COAST_MAX_KM;
}
var onLand = (lat, lon) => coastKm(lat, lon) > 0;
export {
  coastKm,
  onLand
};
